  } catch (error: unknown) {
    liveError = error instanceof Error ? error.message.slice(0, 150) : String(error).slice(0, 150);
    const statusMatch = liveError.match(/status=(\d{3})/);
    if (statusMatch) liveHttpStatus = Number.parseInt(statusMatch[1], 10);
